const listAllowedGuideDraftArtifacts = `-- name: ListAllowedGuideDraftArtifacts :many
SELECT a.id
FROM artifacts a
JOIN support_sessions session ON session.id = $1
JOIN support_requests request ON request.id = session.support_request_id
WHERE a.id = request.initial_screenshot_artifact_id
  AND a.owner_user_id = session.user_id
  AND a.purpose = 'REQUEST_SCREENSHOT'
  AND NOT EXISTS (
      SELECT 1 FROM artifact_deletion_tasks task WHERE task.artifact_id = a.id
  )
UNION
SELECT a.id
FROM artifacts a
JOIN guide_materials material ON material.artifact_id = a.id
JOIN guide_material_batches batch ON batch.id = material.batch_id
JOIN support_sessions session ON session.id = batch.support_session_id
WHERE batch.support_session_id = $1
  AND a.owner_user_id = session.user_id
  AND a.purpose = 'GUIDE_MATERIAL'
  AND NOT EXISTS (
      SELECT 1 FROM artifact_deletion_tasks task WHERE task.artifact_id = a.id
  )
`

func (q *Queries) ListAllowedGuideDraftArtifacts(ctx context.Context, sessionID string) ([]string, error) {
	rows, err := q.db.Query(ctx, listAllowedGuideDraftArtifacts, sessionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

